import{_ as t,o as a,c as e,ag as u}from"./chunks/framework.DzGOF12C.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Philosophy-of-Mind/01-Nagel-What-is-it-like-to-be-a-Bat.md","filePath":"philosophy/Philosophy-of-Mind/01-Nagel-What-is-it-like-to-be-a-Bat.md"}'),q={name:"philosophy/Philosophy-of-Mind/01-Nagel-What-is-it-like-to-be-a-Bat.md"};function i(l,o,r,s,p,n){return a(),e("div",null,[...o[0]||(o[0]=[u('<h2 id="네이글의-박쥐-—-심신-문제와-의식의-주관성" tabindex="-1">네이글의 박쥐 — 심신 문제와 의식의 주관성 <a class="header-anchor" href="#네이글의-박쥐-—-심신-문제와-의식의-주관성" aria-label="Permalink to &quot;네이글의 박쥐 — 심신 문제와 의식의 주관성&quot;">​</a></h2><p>토마스 네이글(Thomas Nagel, 1937~)의 논문은 20세기 심리철학과 마음을 다루는 과학 분야에서 소홀히 다뤄진 <strong>의식의 문제</strong>를 다시 심신 문제의 핵심으로 올려놓은 것으로 평가받는다.</p><blockquote><p>&quot;의식의 문제를 빼버린다면 심신 문제는 그 흥미가 훨씬 덜 할 것이다. 그러나 의식을 포함시키면 심신 문제는 아무런 가망이 없어 보인다.&quot;</p></blockquote><p><strong>심신 문제란?</strong>: 심적 속성이 신체적(물리적) 속성과 맺는 관계에 대한 문제. (예: 심신이원론 — 마음이 따로 존재한다 / 기회원인론 — 신이 생각을 할 때마다 몸을 움직여준다)</p><h2 id="박쥐가-된다는-것이-어떤-것인가" tabindex="-1">&quot;박쥐가 된다는 것이 어떤 것인가&quot; <a class="header-anchor" href="#박쥐가-된다는-것이-어떤-것인가" aria-label="Permalink to &quot;&quot;박쥐가 된다는 것이 어떤 것인가&quot;&quot;">​</a></h2><p>**&quot;what it is like ...&quot;**라는 표현은 의식적 경험을 가짐과 동의어로, 혹은 이를 기준으로 광범위하게 받아들여진다 — 경험의 &quot;주관적 특질&quot;, &quot;감각질&quot; 등과 동의어로 봐도 무방하다.</p><p>다음 질문이 말이 된다면, 의식적 경험이 있다는 것: &quot;키가 40m가 된다는 것은 어떤 것일까?&quot;, &quot;다리가 부러진다는 것은 어떤 것일까?&quot;, &quot;박쥐가 된다는 것은 어떤 것일까?&quot;</p><p>반면 다음 질문은 성립하지 않는다 (일반적으로 믿음·욕구 같은 상태는 의식적 상태로 여겨지지 않으므로): &quot;돌멩이가 된다는 것은 어떤 것일까?&quot;, &quot;죽는다는 것은 어떤 것일까?&quot;, &quot;키가 40m가 되고 싶은 것은 어떤 것일까?&quot;, &quot;지구가 평평하다고 믿는 것은 어떤 것일까?&quot;</p><h2 id="네이글이-보이고자-한-바" tabindex="-1">네이글이 보이고자 한 바 <a class="header-anchor" href="#네이글이-보이고자-한-바" aria-label="Permalink to &quot;네이글이 보이고자 한 바&quot;">​</a></h2><p>(i) 일반적 환원모형이 의식적 경험의 경우에 들어맞지 않는다는 것, (ii) 우리가 현재 환원주의의 주장을 이해하지 못한다는 것.</p><p><strong>환원주의</strong>: 어떤 현상이 다른 현상과 다를 것이 없다는 것 (예: &quot;번개는 전기 방전에 불과하다&quot;). 동일론, 기능주의 등을 포괄하는 말로 이해하면 됨.</p><h2 id="의식적-경험의-주관성" tabindex="-1">의식적 경험의 &#39;주관성&#39; <a class="header-anchor" href="#의식적-경험의-주관성" aria-label="Permalink to &quot;의식적 경험의 &#39;주관성&#39;&quot;">​</a></h2><p>박쥐 사례로부터 이끌어 내는 핵심 주장:</p><ol><li>박쥐가 된다는 것이 어떤 것인가(경험의 주관적 특질)는 특정 **&quot;관점&quot;**과 본질적으로 연결되어 있다 (경험의 현상적 특질은 하나의 관점에서만 &quot;이해&quot;하고 &quot;알 수 있다&quot;).</li><li>그럼에도 불구하고 박쥐가 된다는 것이 어떤 것인가에 관한 <strong>사실이 존재한다</strong>.</li></ol><blockquote><p>&quot;우리 자신의 경험이 상상을 위한 기본적인 재료를 제공하기 때문에 그 상상의 범위는 제약될 수밖에 없다. … 내가 갖고 있는 현재의 경험에 무언가를 덧붙이거나, 그 경험에서 일부는 삭제하거나 … [하는 방식으로] 박쥐의 경험을 상상할 도리는 없다.&quot;</p></blockquote><p><strong>온건한 주장임에 유의</strong>: 다음 두 강한 주장과는 다르다.</p><ul><li>(a) 경험은 그 소유자에게만 속한다는 &#39;사밀성&#39;을 말하는 것이 아니다 — &quot;여기서 문제가 되는 관점은 특정 개인만이 접근할 수 있는 무엇이 아니라, 하나의 **유형(type)**으로서의 관점이다.&quot;</li><li>(b) 경험을 직접 해본 사람만 이해할 수 있다는 것도 아니다 — 상상에 의한 추정도 가능한 것으로 봄.</li></ul><h3 id="i-과-ii-의-긴장-—-주관적인-객관적-사실-이-있다는-말" tabindex="-1">(I)과 (II)의 긴장 — &quot;주관적인 객관적 사실&quot;이 있다는 말? <a class="header-anchor" href="#i-과-ii-의-긴장-—-주관적인-객관적-사실-이-있다는-말" aria-label="Permalink to &quot;(I)과 (II)의 긴장 — &quot;주관적인 객관적 사실&quot;이 있다는 말?&quot;">​</a></h3><blockquote><p>&quot;만약 그 정확한 본성을 파악할 수 없는 사실이 존재한다는 것을 믿을 수 없다고 주장하는 사람이 있다면, 박쥐에 대한 고찰에서 우리 인간의 입장은, 지능을 가진 박쥐나 화성인이 &#39;인간이 된다는 것은 어떤 것인가&#39;를 이해하려고 할 때와 같다는 점을 생각해 볼 필요가 있다. … 우리가 …이해할 수 없는 사항에 대해 그 존재를 부정하거나 논리적 유의미성을 인정하지 않는 태도는 가장 미숙한 형태의 인지적 부조리이다.&quot;</p></blockquote><h2 id="일반적인-환원-모형이-의식에는-적용되지-않는다" tabindex="-1">일반적인 환원 모형이 의식에는 적용되지 않는다 <a class="header-anchor" href="#일반적인-환원-모형이-의식에는-적용되지-않는다" aria-label="Permalink to &quot;일반적인 환원 모형이 의식에는 적용되지 않는다&quot;">​</a></h2><blockquote><p>&quot;환원 과정이란 사물의 진정한 본성에 대한 보다 정확한 관점을 획득하기 위해 <strong>객관성</strong>을 증대시키는 방향으로 향해 나아가는 과정이다.&quot;</p><p>&quot;인간의 시각을 제대로 이해하지 못하는 화성인 과학자도 무지개·번개·구름과 같은 물리적 현상은 이해할 수 있을 것이다. 그러나 화성인 과학자는 인간이 그것들에 대해 갖는 개념이나, 그것들이 인간의 현상 세계 속에서 어떤 위치를 차지하는지는 결코 이해할 수 없을 것이다. … 그 까닭은 이러한 개념은 특정한 관점의 현상과 연결되어 있지만, 그 관점으로 이해되는 사물 자체는 관점과 필연적으로 연결되어 있지 않기 때문이다. … 번개와 같은 현상을 이해하는 경우에는 전적으로 인간적 관점에서 가능한 한 멀리 벗어나는 쪽이 바람직할 것이다.&quot;</p></blockquote><p>반면 <strong>주관적 특질</strong>의 경우:</p><blockquote><p>&quot;경험 자체는 이런 식의 일반적인 환원 패턴에 적합하지 않은 것처럼 보인다. … 인간의 관점이 갖는 특수성을 빼버림으로써 … 인간 경험의 진짜 본성에 좀 더 다가갈 수 있게 되리라고 생각하기 어렵다. 만약 경험의 주관적인 성격이 단일한 특정 관점에 의해서만 충분히 이해될 수 있다면, 객관성을 증대시키기 위한 시도는 오히려 우리를 경험이라는 현상의 본성으로부터 멀어지게 할 것이다.&quot;</p></blockquote><h2 id="환원주의의-이해가능성" tabindex="-1">환원주의의 이해가능성 <a class="header-anchor" href="#환원주의의-이해가능성" aria-label="Permalink to &quot;환원주의의 이해가능성&quot;">​</a></h2><p>네이글이 이 지점까지 보이고자 한 것은 엄밀히 말해 <strong>심-신의 경우가 다른 환원의 경우와 차이가 있다</strong>는 것 — 이 자체가 환원주의에 대한 반박은 아니다. 네이글은 환원주의가 <strong>거짓</strong>이라고 주장하는 대신, 그것이 <strong>이해불가능한 것</strong>이라고 주장한다.</p><blockquote><p>&quot;일반적으로 X는 Y와 동일하다는 말을 들을 때, 우리는 그 명제가 어떻게 참이 되는지 알고 있다. 그러나 어떻게 그것이 참인가에 대한 이해는 어떤 개념적·이론적 배경에 의존할 때 비로소 가능하다. … 그러나 동일성의 두 항이 너무 이질적인 경우, 그 명제가 어떻게 참일 수 있는지는 그리 명확하지 않을 수 있다.&quot;</p></blockquote><p>즉 &quot;X = Y&quot;를 이해할 때는 상이한 두 개념이 어떻게 동일한 대상을 지시하는지 이해해야 한다 — &quot;사랑은 도파민·옥시토신 등 호르몬의 화학 작용&quot;이라는 동일성은 그런대로 이해되지만, &quot;박쥐가 된다는 것 = 어떤 물리적 상태&quot;라는 동일성이 어떻게 참인지는 이해하기 어렵다.</p><p><strong>그럼에도 물리주의가 참이라고 볼 이유는 있을 수 있다</strong> — 참인지 여부와 그 사이의 과정을 이해하는 것은 다르다:</p><blockquote><p>&quot;우리가 어떤 것을 진정으로 이해하지 못할 때에도, 그것이 참이라고 볼만한 증거를 가지는 경우가 있을 수 있다. 가령 곤충의 변태에 대해 잘 모르는 사람이 유충을 무균 용기 속에 밀폐시켰다가 몇 주일 후 용기를 열자 나비가 나타났다면, 용기가 계속 밀폐되어 있었다는 사실을 아는 한 그는 그 나비가 유충이었다고 믿을 만한 이유를 확실히 갖지만, 어떤 의미에서 그러한지는 전혀 알지 못한다.&quot;</p></blockquote>',29)])])}const d=t(q,[["render",i]]);export{c as __pageData,d as default};
